using UnityEngine;

public class WeaponSystem : MonoBehaviour
{
    // BEST: Serialized reference — drag in Inspector
    [SerializeField] private Transform weaponHolder;
    [SerializeField] private Animator playerAnimator;
    [SerializeField] private ParticleSystem muzzleFlash;

    // OK for scene-wide singletons (call once in Start)
    private GameManager gameManager;

    // AVOID: Finding every frame in Update
    void Start()
    {
        // Cache the reference — find once, use many times
        gameManager = FindObjectOfType<GameManager>();

        if (gameManager == null)
        {
            Debug.LogWarning("GameManager not found in scene!");
        }

        // Find child by path
        Transform sight = transform.Find("Model/Sight");
        if (sight != null)
        {
            Debug.Log("Found sight at: " + sight.position);
        }
    }

    void Update()
    {
        // NEVER do this — it searches the entire scene every frame
        // BAD: FindObjectOfType<Player>() every frame

        // GOOD: Use cached reference
        if (gameManager != null && gameManager.IsGameOver)
        {
            return;
        }

        if (Input.GetButtonDown("Fire1"))
        {
            FireWeapon();
        }
    }

    void FireWeapon()
    {
        muzzleFlash?.Play();
        playerAnimator?.SetTrigger("Fire");
    }
}

using UnityEngine;

public class TransformDemo : MonoBehaviour
{
    [SerializeField] private Transform target;
    [SerializeField] private float orbitSpeed = 45f;

    void Update()
    {
        // Move forward in local space (where the object is facing)
        transform.Translate(Vector3.forward * Time.deltaTime * 5f, Space.Self);

        // Move up in world space (ignores object rotation)
        transform.Translate(Vector3.up * Time.deltaTime * 2f, Space.World);

        // Rotate around Y axis
        transform.Rotate(0f, orbitSpeed * Time.deltaTime, 0f);

        // Look at a target object
        if (target != null)
        {
            transform.LookAt(target);
        }

        // Get direction vector to target
        Vector3 direction = (target.position - transform.position).normalized;

        // Move toward target
        transform.position += direction * Time.deltaTime * 3f;

        // Smooth rotation toward target
        Quaternion targetRotation = Quaternion.LookRotation(direction);
        transform.rotation = Quaternion.Slerp(
            transform.rotation, 
            targetRotation, 
            Time.deltaTime * 5f
        );
    }

    void Reset()
    {
        // Called when component is added or Reset is clicked
        // Good for setting default values
        transform.position = Vector3.zero;
        transform.rotation = Quaternion.identity;
    }
}

using UnityEngine;

public class OldInputExample : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float mouseSensitivity = 2f;

    void Update()
    {
        // Keyboard movement with smoothing
        float h = Input.GetAxis("Horizontal");
        float v = Input.GetAxis("Vertical");
        Vector3 move = new Vector3(h, 0, v) * moveSpeed * Time.deltaTime;
        transform.Translate(move);

        // Instant response for competitive games
        float hRaw = Input.GetAxisRaw("Horizontal");
        float vRaw = Input.GetAxisRaw("Vertical");

        // Jump on space press (not hold)
        if (Input.GetKeyDown(KeyCode.Space))
        {
            Jump();
        }

        // Sprint while holding Shift
        bool isSprinting = Input.GetKey(KeyCode.LeftShift);
        float currentSpeed = isSprinting ? moveSpeed * 2f : moveSpeed;

        // Fire weapon
        if (Input.GetButtonDown("Fire1"))
        {
            Fire();
        }

        // Mouse look
        float mouseX = Input.GetAxis("Mouse X") * mouseSensitivity;
        float mouseY = Input.GetAxis("Mouse Y") * mouseSensitivity;
        transform.Rotate(0f, mouseX, 0f);
    }

    void Jump() { /* ... */ }
    void Fire() { /* ... */ }
}

using UnityEngine;

// Character Controller approach
[RequireComponent(typeof(CharacterController))]
public class FPSController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float jumpHeight = 2f;
    [SerializeField] private float gravity = -9.81f;

    private CharacterController controller;
    private Vector3 velocity;
    private bool isGrounded;

    void Awake()
    {
        controller = GetComponent<CharacterController>();
    }

    void Update()
    {
        // Check if grounded
        isGrounded = controller.isGrounded;
        if (isGrounded && velocity.y < 0)
        {
            velocity.y = -0.5f; // Small downward force to stay grounded
        }

        // Movement
        float x = Input.GetAxis("Horizontal");
        float z = Input.GetAxis("Vertical");
        Vector3 move = transform.right * x + transform.forward * z;
        controller.Move(move * moveSpeed * Time.deltaTime);

        // Jump
        if (Input.GetButtonDown("Jump") && isGrounded)
        {
            velocity.y = Mathf.Sqrt(jumpHeight * -2f * gravity);
        }

        // Apply gravity
        velocity.y += gravity * Time.deltaTime;
        controller.Move(velocity * Time.deltaTime);
    }
}

// Rigidbody approach
[RequireComponent(typeof(Rigidbody))]
public class PhysicsPlayer : MonoBehaviour
{
    [SerializeField] private float moveForce = 10f;
    [SerializeField] private float jumpForce = 5f;
    [SerializeField] private float maxSpeed = 10f;

    private Rigidbody rb;
    private bool isGrounded;

    void Awake()
    {
        rb = GetComponent<Rigidbody>();
        rb.freezeRotation = true; // Prevent physics from tumbling the player
    }

    void FixedUpdate() // Physics MUST be in FixedUpdate
    {
        // Movement with force
        float x = Input.GetAxis("Horizontal");
        float z = Input.GetAxis("Vertical");
        Vector3 force = new Vector3(x, 0, z) * moveForce;

        rb.AddForce(force, ForceMode.Force);

        // Clamp velocity to max speed
        Vector3 flatVelocity = new Vector3(rb.velocity.x, 0, rb.velocity.z);
        if (flatVelocity.magnitude > maxSpeed)
        {
            Vector3 limited = flatVelocity.normalized * maxSpeed;
            rb.velocity = new Vector3(limited.x, rb.velocity.y, limited.z);
        }
    }

    void Update()
    {
        // Jump in Update is fine for input detection
        if (Input.GetButtonDown("Jump") && isGrounded)
        {
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
        }
    }

    void OnCollisionStay(Collision collision)
    {
        // Simple ground check
        isGrounded = true;
    }

    void OnCollisionExit(Collision collision)
    {
        isGrounded = false;
    }
}
